const aboutTabContent=[
['story','Our Story','A developer guided by how people live.','ELEVATE creates thoughtfully designed residential environments, connecting architecture, wellbeing and meaningful experiences. Discover our identity, our relationship with One Group and our long-term ambitions.','our-story.html','People / architectural detail'],
['vision','Vision & Approach','Purpose informs every decision.','Our development approach considers the relationship between architecture, private spaces, wellbeing and hospitality. Explore how these ideas come together to support purposeful living.','vision-approach.html','Design / living environment'],
['leadership','Leadership','A shared vision. Considered leadership.','Meet the people guiding ELEVATE’s direction. Discover leadership profiles, areas of responsibility and the experience behind the brand’s long-term residential vision.','leadership.html','Leadership portraits']
];

const aboutPageNav=()=>'<div class="about-page-nav"><nav class="container about-page-links" aria-label="About ELEVATE pages">'+[
['Overview','about'],['Our Story','our-story'],['Vision & Approach','vision-approach'],['Leadership','leadership']
].map(([label,name])=>'<a href="'+name+'.html" '+(page===name?'aria-current="page"':'')+'>'+label+'</a>').join('')+'</nav></div>';
pages.about={title:'About ELEVATE',body:
hero('About ELEVATE','A thoughtful vision.<br>A purposeful future.','Discover the company, the approach and the people shaping a more considered way of living.','About ELEVATE brand banner')+
section('about-overview','<div class="split"><div><div class="eyebrow">Overview / Discover the company</div><h2>Thoughtfully designed spaces.<br>A broader vision for living.</h2><p>ELEVATE is a UAE-based real estate developer creating premium residential environments for modern, purposeful living.</p><p>Our approach brings architecture, wellbeing, meaningful connection and hospitality together. Each development responds to its setting while sharing a considered philosophy of living.</p></div>'+ph('ELEVATE / considered living')+'</div>')+
section('about-pages',head('Explore About ELEVATE','Our story. Our approach. Our people.')+'<div class="grid">'+aboutItems.slice(1).map(t=>card('About ELEVATE',t[0],t[2],t[1],t[0]+' image')).join('')+'</div>',true)+cta()};
['about','our-story','vision-approach','leadership'].forEach(name=>{
pages[name].body=pages[name].body.replace('</section>','</section>'+aboutPageNav());
});
pages.philosophy.body=hero('The ELEVATE philosophy','Five pillars.<br>A fuller way of living.','A home is more than a physical space. It is where routines, relationships and ambitions take shape. Our philosophy connects the environments we create with the lives they support.','Philosophy / lifestyle editorial')+
section('pillars','<div class="eyebrow">Our philosophy</div><h2>Five connected ideas.<br>One way of living.</h2><p class="lead">Our five pillars work together to support a healthier, more balanced and more meaningful everyday life. Explore each perspective below.</p><div class="pillar-tabs" role="tablist" aria-label="Five pillars of living">'+pillars.map((p,i)=>'<button type="button" role="tab" id="pillar-tab-'+p[0].toLowerCase()+'" aria-controls="'+p[0].toLowerCase()+'" aria-selected="'+(!i)+'" tabindex="'+(!i?0:-1)+'"><span>0'+(i+1)+'</span>'+p[0]+'</button>').join('')+'</div>'+
pillars.map((p,i)=>'<div class="pillar-tabpanel" id="'+p[0].toLowerCase()+'" role="tabpanel" aria-labelledby="pillar-tab-'+p[0].toLowerCase()+'" tabindex="0" '+(i?'hidden':'')+'><div class="pillar-tab-layout">'+ph(p[0]+' lifestyle image','large')+'<div class="pillar-tab-copy"><div class="eyebrow">Pillar 0'+(i+1)+' / '+p[0]+'</div><h3>'+p[1]+'</h3><p class="lead">'+p[2]+'</p><p>'+[
'From movement to time outdoors, considered environments can make healthy choices a natural part of the day. Thoughtful spaces support the routines that help residents feel active and well.',
'A sense of calm comes from light, privacy and spaces that allow people to reconnect with themselves. A balance between activity and rest brings a more restorative rhythm to everyday life.',
'Welcoming shared spaces make meeting, gathering and sharing feel natural. Meaningful experiences and everyday moments help people feel part of a wider community.',
'Considered homes make room for personal interests, shared values and the ambitions that matter. Intentional design supports the activities and relationships that give life meaning.',
'Intuitive layouts and thoughtful transitions connect the places and activities of a day. Private and shared spaces work together to make residential life feel more harmonious.'
][i]+'</p><div class="pillar-focus"><span>In everyday life</span><p>'+[
'Room for movement, fresh air and healthy routines.',
'Opportunities to pause, recharge and find balance.',
'Shared experiences that encourage belonging.',
'Space for personal ambitions and meaningful choices.',
'An effortless connection between everyday moments.'
][i]+'</p></div></div></div></div>').join(''),true)+
section('in-practice','<div class="split"><div><div class="eyebrow">How the philosophy informs our developments</div><h2>Ideas made tangible.</h2><p>Our five pillars inform architecture, shared spaces, lifestyle and residential experience. Each development interprets them through its own setting and story.</p>'+btn('Explore projects shaped by our philosophy','developments.html')+'</div>'+ph('Philosophy in practice / project image')+'</div>')+cta();
pages.sitemap.body=pages.sitemap.body.replace('The five philosophy pillars are sections on one page, as specified in the sitemap.','About ELEVATE and Developments have dropdown menus. Philosophy of Living is one complete page with a direct navigation link and five immersive sections.').replace('19 linked HTML pages','20 linked HTML pages');
pages.sitemap.body=pages.sitemap.body.replace('<div class="directory">','<div class="directory"><div><h3>About ELEVATE / Mega menu</h3>'+aboutItems.map(t=>'<a href="'+t[1]+'">'+t[0]+' &#8594;</a>').join('')+'</div><div><h3>Philosophy / One page</h3>'+philosophyItems.map(t=>'<a href="'+t[1]+'">'+t[0]+' &#8594;</a>').join('')+'</div>');
