'<a data-en="Philosophy of Living" href="philosophy.html" '+(page==='philosophy'?'aria-current="page"':'')+'>Philosophy of Living</a>'+
menuMarkup('developments','Developments','developments.html',[
['Developments Overview','developments.html','Explore the portfolio, current projects and upcoming developments.'],
['Mondrian Al Marjan Island Beach Residences','mondrian.html','The complete project story, residences and enquiry journey.'],
['Future Development','future-development.html','Discover a future ELEVATE development.']
],'Explore our portfolio and individual project pages.')+

'<a data-en="News & Media" href="news.html" '+(['news','article','announcement','lifestyle-story','press-coverage'].includes(page)?'aria-current="page"':'')+'>News & Media</a>';

const current=pages[page]||pages['404'];
